+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storedRules.lock) {
+            return storedRules.entries.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        String description = rule.getDescription();
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", description, violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules.lock) {
+            String existingName = storedRules.entries.get(description);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR && existingName != null) {
+                forgetRule(description, existingName);
+                return;
+            }
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                return;
+            }
+
+            String name = existingName != null ? existingName : ruleFileName(description, true);
+            Path target = resolve(name);
+            validateWriteTarget(target, name);
+            FileWriteSnapshot snapshot = write(violations, target);
+
+            Map<String, String> changed = new LinkedHashMap<>(storedRules.entries);
+            if (existingName == null) {
+                changed.put(description, name);
+            }
+            try {
+                if (existingName == null) {
+                    storedRules.writeIndex(changed);
+                    storedRules.entries = changed;
+                }
+            } catch (RuntimeException e) {
