+            }
+        }
+    }
+
+    private void validateWriteTarget(Path target, String name) {
+        if (!isDirectPath(target)) {
+            throw invalidWriteTarget(name);
+        }
+        if (isIndex(target)) {
+            throw invalidWriteTarget(name);
+        }
+        if (Files.isSymbolicLink(target)) {
+            try {
+                if (!target.toRealPath().getParent().equals(storeFolder.toPath())) {
+                    throw invalidWriteTarget(name);
+                }
+            } catch (IOException e) {
+                throw invalidWriteTarget(name);
+            }
+        }
+    }
+
+    private StoreUpdateFailedException invalidWriteTarget(String name) {
+        return new StoreUpdateFailedException(String.format(
+                "Cannot write violation file '%s': it must resolve to a file directly in the store folder and must not be the index",
+                name));
+    }
+
+    private void forgetRule(String description, String name) {
+        Path target = resolve(name);
+        if (isIndex(target)) {
+            throw invalidWriteTarget(name);
+        }
+        boolean shared = isSharedWithAnother(description, target);
+        FileDeleteSnapshot snapshot = null;
+        if (!shared) {
+            snapshot = deleteFile(target);
+        }
+
+        Map<String, String> changed = new LinkedHashMap<>(storedRules.entries);
+        changed.remove(description);
+        try {
+            storedRules.writeIndex(changed);
+            storedRules.entries = changed;
+        } catch (RuntimeException e) {
+            if (snapshot != null) {
+                snapshot.restore();
+            }
+            throw e;
+        }
+    }
+
+    private boolean isSharedWithAnother(String description, Path target) {
+        for (Map.Entry<String, String> entry : storedRules.entries.entrySet()) {
+            if (entry.getKey().equals(description)) {
+                continue;
+            }
+            if (entry.getValue().equals(storedRules.entries.get(description))) {
+                return true;
+            }
+            Path other = resolve(entry.getValue());
+            if (sameFile(target, other)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private FileWriteSnapshot write(List<String> violations, Path target) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        byte[] bytes = builder.toString().getBytes(UTF_8);
+        try {
+            return FileWriteSnapshot.write(target, bytes);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private String ruleFileName(String description, boolean update) {
+        String name = ruleViolationFileNameStrategy.createRuleFileName(description);
+        if (name == null || name.trim().isEmpty()) {
+            RuntimeException failure = update
+                    ? new StoreUpdateFailedException("The rule violation file name strategy returned no name")
+                    : new StoreInitializationFailedException("The rule violation file name strategy returned no name");
+            throw failure;
+        }
+        return name;
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        String description = rule.getDescription();
+        synchronized (storedRules.lock) {
+            String name = storedRules.entries.get(description);
+            checkArgument(name != null, "No rule stored with description '%s'", description);
+            List<String> result = readLines(name);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", description, result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String fileName) {
+        String violationsText = readStoreFile(fileName);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            return ensureUnixLineBreaks(new String(toByteArray(resolve(fileName).toFile()), UTF_8));
+        } catch (IOException | InvalidPathException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private Path resolve(String name) {
+        try {
+            return storeFolder.toPath().resolve(name).normalize();
+        } catch (InvalidPathException e) {
+            return null;
+        }
+    }
+
+    private boolean isDirectPath(Path path) {
+        return path != null && storeFolder.toPath().equals(path.getParent());
+    }
+
+    private boolean isIndex(Path path) {
+        if (path == null) {
+            return false;
+        }
+        Path index = storeFolder.toPath().resolve(STORED_RULES_FILE_NAME);
+        if (path.equals(index)) {
+            return true;
+        }
+        return Files.exists(path, LinkOption.NOFOLLOW_LINKS) && sameFile(path, index);
+    }
+
+    private boolean sameFile(Path first, Path second) {
+        if (first == null || second == null || !Files.exists(first, LinkOption.NOFOLLOW_LINKS)
+                || !Files.exists(second, LinkOption.NOFOLLOW_LINKS)) {
+            return false;
+        }
+        try {
+            return Files.isSameFile(first, second);
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private IntegrityReport inspect(StoreState state) {
+        List<Entry> entries = new ArrayList<>();
+        for (Map.Entry<String, String> entry : state.entries.entrySet()) {
+            String derived = ruleFileName(entry.getKey(), false);
+            Path path = resolve(entry.getValue());
+            boolean regular = isRegularFile(path);
+            boolean direct = regular && leadsDirectlyIntoFolder(path);
+            boolean broken = !direct;
+            boolean resolved = regular && hasNoViolations(path);
+            entries.add(new Entry(entry.getKey(), entry.getValue(), derived, path, broken, resolved));
+        }
+
+        Set<Entry> shared = new HashSet<>();
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                Entry first = entries.get(i);
+                Entry second = entries.get(j);
+                if (first.name.equals(second.name) || sameFile(first.path, second.path)) {
+                    shared.add(first);
+                    shared.add(second);
+                }
+            }
+        }
+        for (Entry entry : entries) {
+            entry.shared = shared.contains(entry);
+            entry.misplaced = !entry.name.equals(entry.derived);
+            entry.colliding = entries.stream().anyMatch(other -> other != entry && other.derived.equals(entry.derived));
+            entry.occupied = entry.misplaced && isOccupied(entry, entries);
+        }
+
+        List<String> unowned = new ArrayList<>();
+        Path index = state.index;
+        try (DirectoryStream<Path> children = Files.newDirectoryStream(state.folder)) {
+            for (Path child : children) {
+                if (child.equals(index) || !Files.isRegularFile(child, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = entries.stream().anyMatch(entry -> sameFile(entry.path, child));
+                if (!owned) {
+                    unowned.add(child.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(unowned);
+        return new IntegrityReport(entries, unowned);
+    }
