archunit.group=com.tngtech.archunit
archunit.version=1.6.0-SNAPSHOT
org.gradle.jvmargs=--add-exports jdk.compiler/com.sun.tools.javac.code=ALL-UNNAMED --add-exports jdk.compiler/com.sun.tools.javac.file=ALL-UNNAMED --add-exports jdk.compiler/com.sun.tools.javac.parser=ALL-UNNAMED --add-exports jdk.compiler/com.sun.tools.javac.tree=ALL-UNNAMED --add-exports jdk.compiler/com.sun.tools.javac.util=ALL-UNNAMED --add-exports jdk.compiler/com.sun.tools.javac.api=ALL-UNNAMED
plugins {
    id 'archunit.base-conventions'
    id 'com.gradleup.shadow' version '9.6.1' apply false
    id 'com.github.spotbugs' version '6.5.10' apply false
    id "io.github.gradle-nexus.publish-plugin" version "2.0.0" apply false
    id "com.diffplug.spotless" version "8.10.0" apply false
    id 'io.github.ben-manes.versions' version '0.61.0'
}

def appAndSourceUrl = 'https://github.com/TNG/ArchUnit'

ext {
    year = "${Calendar.getInstance().get(Calendar.YEAR)}"
    app = [
            name   : 'ArchUnit',
            urls   : [
                    entry : appAndSourceUrl,
                    doc   : appAndSourceUrl,
                    issues: "${appAndSourceUrl}/issues",
                    source: appAndSourceUrl
            ],
            gitRepo: 'git@github.com:TNG/ArchUnit.git',
            license: [
                    name: 'The Apache Software License, Version 2.0',
                    url : 'http://www.apache.org/licenses/LICENSE-2.0.txt'
            ]
    ]
    company = [
            name: 'TNG Technology Consulting GmbH',
            url : 'https://www.tngtech.com/'
    ]

    thirdPartyRelocationPackage = 'com.tngtech.archunit.thirdparty'
    asmRelocationPackage = "${thirdPartyRelocationPackage}.org.objectweb.asm"
    googleRelocationPackage = "${thirdPartyRelocationPackage}.com.google"

    dependency = [
            addGuava             : { dependencyHandler ->
                dependencyHandler(libs.guava) {
                    exclude module: 'listenablefuture'
                    exclude module: 'jspecify'
                    exclude module: 'error_prone_annotations'
                    exclude module: 'j2objc-annotations'
                }
            },
    ]

    minSupportedJavaVersion = JavaVersion.VERSION_1_8
    maxSupportedJavaVersion = JavaVersion.VERSION_25
    isTestBuild = project.hasProperty('testJavaVersion')
    configuredTestJavaVersion = project.findProperty('testJavaVersion')?.toString()?.with { JavaVersion.toVersion(it) }
    assert configuredTestJavaVersion <= maxSupportedJavaVersion:
            "Cannot test with ${configuredTestJavaVersion} because it is higher than max supported version ${maxSupportedJavaVersion}"

    postfixedJar = { File jarFile, String postfix ->
        new File(jarFile.parentFile, jarFile.name.replaceAll(/\.jar$/, "-${postfix}.jar"))
    }

    tempJar = { File jarFile -> postfixedJar(jarFile, 'tmp') }

    productionProjects = [
            project(':archunit'),
            project(':archunit-junit'),
            project(':archunit-junit4'),
            project(':archunit-junit5-api'),
            project(':archunit-junit5-engine-api'),
            project(':archunit-junit5-engine'),
            project(':archunit-junit5'),
            project(':archunit-junit6-api'),
            project(':archunit-junit6-engine-api'),
            project(':archunit-junit6-engine'),
            project(':archunit-junit6')]

    currentScriptRootOf = { it.buildscript.sourceFile.parentFile }
    scriptRelativePath = { context, fileName -> new File(currentScriptRootOf(context), fileName) }
}

description = 'A Java architecture test library, to specify and assert architecture rules in plain Java'

task showJdkVersion {
    println "Configured JDK: ${JavaVersion.current()}"
}

task clean {
    doLast {
        project.buildDir.deleteDir()
    }
}

apply from: 'build-steps/build-steps.gradle'
plugins {
    id 'archunit.java-release-conventions'
    id 'archunit.java-junit-conventions'
    id 'archunit.self-test-conventions'
}

ext.moduleName = 'com.tngtech.archunit'

dependencies {
    api libs.slf4j
    implementation libs.asm
    dependency.addGuava { dependencyNotation, config -> implementation(dependencyNotation, config) }

    testImplementation libs.log4j.api
    testImplementation libs.log4j.core
    testImplementation libs.junit4
    testImplementation libs.mockito
    testImplementation libs.mockito.junit5
    testImplementation libs.assertj
    testImplementation(libs.assertj.guava) {
        exclude module: 'assertj-core'
        exclude module: 'guava'
    }

    // This subproject is JUnit-agnostic. We run the architecture self-tests using JUnit5 because of Java 8 compatibility.
    archTestImplementation project(path: ':archunit-junit5')
    archTestRuntimeOnly libs.junit5PlatformLauncher
}

shadowJar {
    exclude 'META-INF/**'

    dependencies {
        exclude(dependency("${libs.slf4j.get()}"))
    }
}

repackaging {
    repackagesAsm true
}

/* Besides SLF4J we'll shadow everything we need into the JAR to avoid conflicts with other libraries*/
publishing {
    publications {
        mavenJava {
            pom.withXml {
                def deps = asNode().dependencies.first() // there is only one "dependencies" element
                deps.children().removeIf { dep ->
                    dep.artifactId.text() != 'slf4j-api' || dep.scope.text() != 'compile'
                }
            }
        }
    }
}

archUnitTest {
    providesTestJar = true
}

def jdk9MainDirs = ['src/jdk9main/java']
def jdk9TestDirs = ['src/jdk9test/java']
def jdk16TestDirs = ['src/jdk16test/java']
def jdk25TestDirs = ['src/jdk25test/java']
sourceSets {
    jdk9main {
        java {
            srcDirs = jdk9MainDirs
        }
        compileClasspath += sourceSets.main.compileClasspath + sourceSets.main.output.classesDirs
    }
    jdk9test {
        java {
            srcDirs = jdk9TestDirs
        }
        compileClasspath += sourceSets.test.compileClasspath + sourceSets.jdk9main.output.classesDirs
        runtimeClasspath += sourceSets.test.runtimeClasspath
    }
    jdk16test {
        java {
            srcDirs = jdk16TestDirs
        }
        compileClasspath += sourceSets.test.compileClasspath + sourceSets.jdk9main.output.classesDirs
        runtimeClasspath += sourceSets.test.runtimeClasspath
    }
    jdk25test {
        java {
            srcDirs = jdk25TestDirs
        }
        compileClasspath += sourceSets.test.compileClasspath + sourceSets.jdk9main.output.classesDirs
        runtimeClasspath += sourceSets.test.runtimeClasspath
    }
}

dependencies {
    jdk9mainImplementation sourceSets.main.output
    jdk9testImplementation sourceSets.test.output
    jdk9testImplementation sourceSets.test.compileClasspath
    jdk9testImplementation sourceSets.jdk9main.output
    jdk16testImplementation sourceSets.test.output
    jdk16testImplementation sourceSets.test.compileClasspath
    jdk25testImplementation sourceSets.test.output
    jdk25testImplementation sourceSets.test.compileClasspath

    runtimeOnly sourceSets.jdk9main.output
}

compileJdk9mainJava {
    dependsOn(compileJava)
    ext.minimumJavaVersion = JavaVersion.VERSION_1_9

    destinationDirectory.set(compileJava.destinationDirectory.get())
}
javadoc.dependsOn(compileJdk9mainJava)
spotbugsMain.dependsOn(compileJdk9mainJava)
compileTestJava.dependsOn(compileJdk9mainJava)

compileJdk9testJava.with {
    ext.minimumJavaVersion = JavaVersion.VERSION_1_9
}

compileJdk16testJava.with {
    ext.minimumJavaVersion = JavaVersion.VERSION_16
}

compileJdk25testJava.with {
    ext.minimumJavaVersion = JavaVersion.VERSION_25
}

task jdk9Test(type: Test) {
    ext.minimumJavaVersion = JavaVersion.VERSION_1_9

    testClassesDirs = sourceSets.jdk9test.output.classesDirs
    classpath = sourceSets.jdk9test.runtimeClasspath
}

task jdk16Test(type: Test) {
    ext.minimumJavaVersion = JavaVersion.VERSION_16

    testClassesDirs = sourceSets.jdk16test.output.classesDirs
    classpath = sourceSets.jdk16test.runtimeClasspath
}

task jdk25Test(type: Test) {
    ext.minimumJavaVersion = JavaVersion.VERSION_25

    testClassesDirs = sourceSets.jdk25test.output.classesDirs
    classpath = sourceSets.jdk25test.runtimeClasspath
}

assemble.dependsOn compileJdk9mainJava

test.finalizedBy(jdk9Test, jdk16Test, jdk25Test)

[spotbugsJdk9test, spotbugsJdk16test, spotbugsJdk25test]*.enabled = false


