/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} stores the violations of every rule in a
 * dedicated file and keeps an index in the same folder.
 *
 * @PublicAPI(usage = ACCESS)
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
    private static final Pattern DESCRIPTION_WORD = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_DEFAULT = "ignore";
    private static final String INTEGRITY_REPAIR = "repair";
    private static final String INTEGRITY_FAIL = "fail";
    private static final String INTEGRITY_IGNORE = "ignore";

    private static final ConcurrentHashMap<String, StoreState> STORES_BY_PATH = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy constructorStrategy;
    private final boolean customStrategy;

    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private File storeFolder;
    private StoreState storedRules;
    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private IntegrityMode integrityMode;
    private boolean randomFileNames;

    /**
     * Creates a standard store that names new rule violation files by random UUIDs.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        constructorStrategy = null;
        customStrategy = false;
    }

    /**
     * Creates a store with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how rule violation file names are derived
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        if (ruleViolationFileNameStrategy == null) {
            throw new NullPointerException("ruleViolationFileNameStrategy");
        }
        constructorStrategy = ruleViolationFileNameStrategy;
        customStrategy = true;
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(
                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(
                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        ruleViolationFileNameStrategy = configureStrategy(properties);
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires %s.%s=true",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        File configuredFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
        File configuredIndex = new File(configuredFolder, STORED_RULES_FILE_NAME);
        StoreState state = getOrCreateStoreState(configuredIndex);
        synchronized (state.lock) {
            File actualFolder = prepareFolderAndIndex(configuredFolder, configuredIndex);
            state.folder = actualFolder.toPath();
            state.index = new File(actualFolder, STORED_RULES_FILE_NAME).toPath();
            state.load();
            if (integrityMode != IntegrityMode.IGNORE) {
                IntegrityReport report = inspect(state);
                if (integrityMode == IntegrityMode.FAIL) {
                    if (report.hasProblems()) {
                        throw new StoreInitializationFailedException(report.message(actualFolder));
                    }
                } else {
                    try {
                        repair(state, report);
                    } catch (StoreUpdateFailedException e) {
                        throw new StoreInitializationFailedException(e);
                    }
                }
            }
            storeFolder = actualFolder;
            storedRules = state;
        }
        log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(),
                new File(storeFolder, STORED_RULES_FILE_NAME).getAbsolutePath());
    }

    private RuleViolationFileNameStrategy configureStrategy(Properties properties) {
        if (customStrategy) {
            if (properties.stringPropertyNames().contains(FILE_NAMES_PROPERTY_NAME)) {
                throw new StoreInitializationFailedException(String.format(
                        "%s cannot be configured for a store constructed with a custom %s",
                        FILE_NAMES_PROPERTY_NAME, RuleViolationFileNameStrategy.class.getSimpleName()));
            }
            return constructorStrategy;
        }

        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, "random");
        if ("random".equals(configured)) {
            randomFileNames = true;
        }

        List<String> getStoredUnsolvedViolations() {
            return storedUnsolvedViolations;
        }
    }

    private static class ViolationStoreLineBreakAdapter {
        private final ViolationStore store;

        ViolationStoreLineBreakAdapter(ViolationStore store) {
            this.store = checkNotNull(store);
        }

        void initialize(Properties properties) {
            store.initialize(properties);
        }

        boolean contains(ArchRule rule) {
            return store.contains(normalizeDescription(rule));
        }

        List<String> getViolations(ArchRule rule) {
            return ensureUnixLineBreaks(store.getViolations(normalizeDescription(rule)));
        }

        void save(ArchRule rule, List<String> violations) {
            store.save(normalizeDescription(rule), ensureUnixLineBreaks(violations));
        }

        private ArchRule normalizeDescription(ArchRule rule) {
            String description = ensureUnixLineBreaks(rule.getDescription());
            return description.equals(rule.getDescription()) ? rule : new DescriptionNormalizedRule(rule, description);
