    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(
                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(
                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
        ruleViolationFileNameStrategy = configureStrategy(properties);
        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires %s.%s=true",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        File configuredFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
        File configuredIndex = new File(configuredFolder, STORED_RULES_FILE_NAME);
        StoreState state = getOrCreateStoreState(configuredIndex);
        synchronized (state.lock) {
            File actualFolder = prepareFolderAndIndex(configuredFolder, configuredIndex);
            storeFolder = actualFolder;
            state.folder = actualFolder.toPath();
            state.index = new File(actualFolder, STORED_RULES_FILE_NAME).toPath();
            state.load();
            if (integrityMode != IntegrityMode.IGNORE) {
                IntegrityReport report = inspect(state);
                if (integrityMode == IntegrityMode.FAIL) {
                    if (report.hasProblems()) {
                        throw new StoreInitializationFailedException(report.message(actualFolder));
                    }
                } else {
                    try {
                        repair(state, report);
                    } catch (StoreUpdateFailedException e) {
                        throw new StoreInitializationFailedException(e);
                    }
                }
            }
            storedRules = state;
        }
        log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(),
                new File(storeFolder, STORED_RULES_FILE_NAME).getAbsolutePath());
    }

    private RuleViolationFileNameStrategy configureStrategy(Properties properties) {
        if (customStrategy) {
            if (properties.stringPropertyNames().contains(FILE_NAMES_PROPERTY_NAME)) {
                throw new StoreInitializationFailedException(String.format(
                        "%s cannot be configured for a store constructed with a custom %s",
                        FILE_NAMES_PROPERTY_NAME, RuleViolationFileNameStrategy.class.getSimpleName()));
            }
            return constructorStrategy;
        }

        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, "random");
        if ("random".equals(configured)) {
            randomFileNames = true;
            return description -> UUID.randomUUID().toString();
        }
        if ("description".equals(configured)) {
            randomFileNames = false;
            return new DescriptionFileNameStrategy();
        }
        randomFileNames = false;
        try {
            Class<?> strategyType = Class.forName(configured);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
            }
            @SuppressWarnings("unchecked")
            Class<? extends RuleViolationFileNameStrategy> typedType =
                    (Class<? extends RuleViolationFileNameStrategy>) strategyType;
            Constructor<? extends RuleViolationFileNameStrategy> constructor = typedType.getConstructor();
            return constructor.newInstance();
        } catch (Exception e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate %s configured through %s='%s' (it must be a strategy with a public no-argument constructor)",
                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
        }
    }

    private StoreState getOrCreateStoreState(File configuredIndex) {
        try {
            String path = configuredIndex.getCanonicalPath();
            return STORES_BY_PATH.computeIfAbsent(path, ignored -> new StoreState());
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private File prepareFolderAndIndex(File configuredFolder, File configuredIndex) {
        Path folderPath = configuredFolder.toPath();
        boolean indexExists = Files.exists(configuredIndex.toPath(), LinkOption.NOFOLLOW_LINKS);
        if (!indexExists && (integrityMode == IntegrityMode.FAIL || !storeCreationAllowed)) {
            throw missingIndex(configuredIndex);
        }

        try {
            if (!Files.exists(folderPath, LinkOption.NOFOLLOW_LINKS)) {
                if (integrityMode == IntegrityMode.FAIL || !storeCreationAllowed || !configuredFolder.mkdirs()
                        && !configuredFolder.isDirectory()) {
                    throw missingIndex(configuredIndex);
                }
            }
            if (!Files.isDirectory(folderPath)) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot use store folder %s because it is not a directory", configuredFolder.getAbsolutePath()));
            }
            File actualFolder = configuredFolder.getCanonicalFile();
            Path actualIndex = actualFolder.toPath().resolve(STORED_RULES_FILE_NAME);
            if (!Files.exists(actualIndex, LinkOption.NOFOLLOW_LINKS)) {
                if (integrityMode == IntegrityMode.FAIL || !storeCreationAllowed) {
                    throw missingIndex(configuredIndex);
                }
                Files.createFile(actualIndex);
            }
            if (!Files.isRegularFile(actualIndex, LinkOption.NOFOLLOW_LINKS)) {
                throw new StoreInitializationFailedException(String.format(
                        "The index %s is not a regular file directly in the store folder", actualIndex));
            }
            return actualFolder;
        } catch (StoreInitializationFailedException e) {
            throw e;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

