    private Path resolve(String name) {
        try {
            return storeFolder.toPath().resolve(name).normalize();
        } catch (InvalidPathException e) {
            return null;
        }
    }

    private boolean isDirectPath(Path path) {
        return path != null && storeFolder.toPath().equals(path.getParent());
    }

    private boolean isIndex(Path path) {
        if (path == null) {
            return false;
        }
        Path index = storeFolder.toPath().resolve(STORED_RULES_FILE_NAME);
        if (path.equals(index)) {
            return true;
        }
        return Files.exists(path, LinkOption.NOFOLLOW_LINKS) && sameFile(path, index);
    }

    private boolean sameFile(Path first, Path second) {
        if (first == null || second == null || !Files.exists(first, LinkOption.NOFOLLOW_LINKS)
                || !Files.exists(second, LinkOption.NOFOLLOW_LINKS)) {
            return false;
        }
        try {
            return Files.isSameFile(first, second);
        } catch (IOException e) {
            return false;
        }
    }

    private IntegrityReport inspect(StoreState state) {
        List<Entry> entries = new ArrayList<>();
        for (Map.Entry<String, String> entry : state.entries.entrySet()) {
            // A random strategy can name a new file, but cannot produce a meaningful
            // second name against which an existing entry could be checked.
            String derived = randomFileNames ? entry.getValue() : ruleFileName(entry.getKey(), false);
            Path path = resolve(entry.getValue());
            boolean regular = isRegularFile(path);
            boolean direct = regular && leadsDirectlyIntoFolder(path);
            boolean broken = !direct;
            boolean resolved = regular && hasNoViolations(path);
            entries.add(new Entry(entry.getKey(), entry.getValue(), derived, path, broken, resolved));
        }

        Set<Entry> shared = new HashSet<>();
        for (int i = 0; i < entries.size(); i++) {
            for (int j = i + 1; j < entries.size(); j++) {
                Entry first = entries.get(i);
                Entry second = entries.get(j);
                if (first.name.equals(second.name) || sameFile(first.path, second.path)) {
                    shared.add(first);
                    shared.add(second);
                }
            }
        }
        for (Entry entry : entries) {
            entry.shared = shared.contains(entry);
            entry.misplaced = !entry.name.equals(entry.derived);
            entry.colliding = entries.stream().anyMatch(other -> other != entry && other.derived.equals(entry.derived));
            entry.occupied = entry.misplaced && isOccupied(entry, entries);
        }

        List<String> unowned = new ArrayList<>();
        Path index = state.index;
        try (DirectoryStream<Path> children = Files.newDirectoryStream(state.folder)) {
            for (Path child : children) {
                if (child.equals(index) || !Files.isRegularFile(child) || !leadsDirectlyIntoFolder(child)) {
                    continue;
                }
                boolean owned = entries.stream().anyMatch(entry -> sameFile(entry.path, child));
                if (!owned) {
                    unowned.add(child.getFileName().toString());
                }
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        Collections.sort(unowned);
        return new IntegrityReport(entries, unowned);
    }

    private boolean isOccupied(Entry entry, List<Entry> entries) {
        if (!isDirectPath(resolve(entry.derived))) {
            return true;
        }
        if (entries.stream().anyMatch(other -> other != entry && other.name.equals(entry.derived))) {
            return true;
        }
        Path derived = resolve(entry.derived);
        return Files.exists(derived, LinkOption.NOFOLLOW_LINKS);
    }

    private boolean isRegularFile(Path path) {
        return path != null && Files.isRegularFile(path);
    }

    private boolean leadsDirectlyIntoFolder(Path path) {
        if (!isDirectPath(path)) {
            return false;
        }
        try {
            return path.toRealPath().getParent().equals(storeFolder.toPath());
        } catch (IOException e) {
            return false;
        }
    }

    private boolean hasNoViolations(Path path) {
        try {
            String contents = new String(Files.readAllBytes(path), UTF_8);
            for (int i = 0; i < contents.length(); i++) {
                char character = contents.charAt(i);
                if (character != '\n' && character != '\r') {
                    return false;
                }
            }
            return true;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void repair(StoreState state, IntegrityReport report) {
        Map<String, String> changed = new LinkedHashMap<>(state.entries);
        List<Runnable> undo = new ArrayList<>();
        try {
            for (Entry entry : report.entries) {
                if (entry.shared) {
                    continue;
                }
                if (entry.broken || entry.resolved) {
                    if (entry.resolved) {
                        FileDeleteSnapshot deleted = deleteFile(entry.path);
                        if (deleted != null) {
                            undo.add(deleted::restore);
                        }
                    }
                    changed.remove(entry.description);
                } else if (entry.misplaced && !entry.colliding && !entry.occupied && !isIndex(entry.path)) {
                    FileMoveSnapshot moved = moveFile(entry.path, resolve(entry.derived));
                    undo.add(moved::restore);
                    changed.put(entry.description, entry.derived);
                }
            }
            if (!changed.equals(state.entries)) {
                state.writeIndex(changed);
                state.entries = changed;
            }
        } catch (RuntimeException e) {
            for (int i = undo.size() - 1; i >= 0; i--) {
                try {
                    undo.get(i).run();
                } catch (RuntimeException ignored) {
                    log.warn("Could not roll back an integrity repair", ignored);
                }
            }
            throw e;
        }
    }

    private FileDeleteSnapshot deleteFile(Path path) {
        if (path == null || !Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
            return null;
        }
        try {
            return FileDeleteSnapshot.delete(path);
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private FileMoveSnapshot moveFile(Path source, Path destination) {
        if (source == null || destination == null) {
            throw new StoreInitializationFailedException("Cannot move an invalid rule violation file path");
        }
        try {
            return FileMoveSnapshot.move(source, destination);
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

