        @Override
        public String createRuleFileName(String ruleDescription) {
            String normalized = ruleDescription.replace("\r\n", "\n");
            Matcher matcher = DESCRIPTION_WORD.matcher(normalized);
            String word = matcher.find() ? matcher.group(1) : "rule";
            return word + "-" + sha256(normalized);
        }

        private static String sha256(String value) {
            try {
                byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
                StringBuilder result = new StringBuilder(digest.length * 2);
                for (byte part : digest) {
                    result.append(String.format("%02x", part & 0xff));
                }
                return result.toString();
            } catch (NoSuchAlgorithmException e) {
                throw new IllegalStateException(e);
            }
        }
    }

