    private void validateWriteTarget(Path target, String name) {
        if (!isDirectPath(target)) {
            throw invalidWriteTarget(name);
        }
        if (isIndex(target)) {
            throw invalidWriteTarget(name);
        }
        if (Files.isSymbolicLink(target)) {
            try {
                if (!target.toRealPath().getParent().equals(storeFolder.toPath())) {
                    throw invalidWriteTarget(name);
                }
            } catch (IOException e) {
                throw invalidWriteTarget(name);
            }
