    private void forgetRule(String description, String name) {
        Path target = resolve(name);
        if (isIndex(target)) {
            throw invalidWriteTarget(name);
        }
        boolean shared = isSharedWithAnother(description, target);
        FileDeleteSnapshot snapshot = null;
        if (!shared) {
            snapshot = deleteFile(target);
        }

        Map<String, String> changed = new LinkedHashMap<>(storedRules.entries);
        changed.remove(description);
        try {
            storedRules.writeIndex(changed);
            storedRules.entries = changed;
        } catch (RuntimeException e) {
            if (snapshot != null) {
                snapshot.restore();
            }
            throw e;
        }
